content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #1a1a1a;
  color: #f0f0f0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.piano-app {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #2b2b2b;
  padding: 24px;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  max-width: 640px;
  width: 100%;
}

.header {
  margin-bottom: 20px;
  text-align: center;
}

.header h1 {
  font-size: 1.8rem;
  margin-bottom: 8px;
  color: #fff;
}

.header p {
  font-size: 0.9rem;
  color: #aaa;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
  align-items: center;
}

.btn {
  background-color: #4a4a4a;
  color: #fff;
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: #5a5a5a;
}

.btn:active {
  transform: scale(0.96);
}

.slider {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  color: #ccc;
}

.slider input[type="range"] {
  accent-color: #3b82f6;
  cursor: pointer;
}

.keyboard {
  position: relative;
  display: flex;
  height: 200px;
  background: #111;
  padding: 10px;
  border-radius: 8px;
  box-shadow: inset 0 4px 6px rgba(0, 0, 0, 0.6);
  user-select: none;
  margin-bottom: 24px;
}

.white-key {
  position: relative;
  width: 48px;
  height: 180px;
  background: #fdfdfd;
  border: 1px solid #ccc;
  border-radius: 0 0 6px 6px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 12px;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  z-index: 1;
}

.white-key.active {
  background: #d4d4d4;
  transform: translateY(2px);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.2);
}

.black-key {
  position: absolute;
  width: 30px;
  height: 110px;
  background: #222;
  border-radius: 0 0 4px 4px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 8px;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.4);
  z-index: 2;
}

.black-key.active {
  background: #444;
  transform: translateY(2px);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.3);
}

.key-label {
  font-size: 0.75rem;
  font-weight: bold;
  color: #666;
  pointer-events: none;
}

.black-key .key-label {
  color: #aaa;
  font-size: 0.65rem;
}

.history-panel {
  width: 100%;
  background: #222;
  padding: 12px 16px;
  border-radius: 8px;
  max-height: 120px;
  overflow-y: auto;
  font-size: 0.85rem;
  color: #aaa;
  border: 1px solid #333;
}

.history-panel h3 {
  font-size: 0.9rem;
  color: #fff;
  margin-bottom: 6px;
}

export interface NoteItem {
  id: string;
  name: string;
  freq: number;
  isBlack: boolean;
  shortcut: string;
  label: string;
}

export interface PianoSettings {
  volume: number;
  waveType: OscillatorType;
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { NoteItem, PianoSettings } from '../types';

interface PianoProps {
  settings: PianoSettings;
  onNotePlay?: (noteName: string) => void;
  activeNoteId?: string | null;
}

const NOTES: NoteItem[] = [
  { id: 'C4', name: 'C4', freq: 261.63, isBlack: false, shortcut: 'a', label: 'A' },
  { id: 'Db4', name: 'C#4', freq: 277.18, isBlack: true, shortcut: 'w', label: 'W' },
  { id: 'D4', name: 'D4', freq: 293.66, isBlack: false, shortcut: 's', label: 'S' },
  { id: 'Eb4', name: 'D#4', freq: 311.13, isBlack: true, shortcut: 'e', label: 'E' },
  { id: 'E4', name: 'E4', freq: 329.63, isBlack: false, shortcut: 'd', label: 'D' },
  { id: 'F4', name: 'F4', freq: 349.23, isBlack: false, shortcut: 'f', label: 'F' },
  { id: 'Gb4', name: 'F#4', freq: 369.99, isBlack: true, shortcut: 't', label: 'T' },
  { id: 'G4', name: 'G4', freq: 392.00, isBlack: false, shortcut: 'g', label: 'G' },
  { id: 'Ab4', name: 'G#4', freq: 415.30, isBlack: true, shortcut: 'y', label: 'Y' },
  { id: 'A4', name: 'A4', freq: 440.00, isBlack: false, shortcut: 'h', label: 'H' },
  { id: 'Bb4', name: 'A#4', freq: 466.16, isBlack: true, shortcut: 'u', label: 'U' },
  { id: 'B4', name: 'B4', freq: 493.88, isBlack: false, shortcut: 'j', label: 'J' },
  { id: 'C5', name: 'C5', freq: 523.25, isBlack: false, shortcut: 'k', label: 'K' },
];

export default function Piano({ settings, onNotePlay, activeNoteId }: PianoProps) {
  const [activeKeys, setActiveKeys] = useState<Record<string, boolean>>({});
  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playNote = useCallback((note: NoteItem) => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = settings.waveType;
      osc.frequency.setValueAtTime(note.freq, ctx.currentTime);

      const vol = Math.max(0, Math.min(1, settings.volume));
      gain.gain.setValueAtTime(vol * 0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 1.0);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 1.0);

      setActiveKeys((prev) => ({ ...prev, [note.id]: true }));
      setTimeout(() => {
        setActiveKeys((prev) => ({ ...prev, [note.id]: false }));
      }, 200);

      onNotePlay?.(note.name);
    } catch {
      // Audio error fallback
    }
  }, [settings, onNotePlay]);

  useEffect(() => {
    if (activeNoteId) {
      const note = NOTES.find((n) => n.id === activeNoteId || n.name === activeNoteId);
      if (note) {
        playNote(note);
      }
    }
  }, [activeNoteId, playNote]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const note = NOTES.find((n) => n.shortcut.toLowerCase() === e.key.toLowerCase());
      if (note) {
        playNote(note);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [playNote]);

  let whiteKeyIndex = 0;

  return (
    <div className="keyboard">
      {NOTES.map((note) => {
        const isActive = activeKeys[note.id];
        if (!note.isBlack) {
          const currentWhiteIndex = whiteKeyIndex++;
          const leftPos = currentWhiteIndex * 48;
          return (
            <div
              key={note.id}
              className={`white-key ${isActive ? 'active' : ''}`}
              style={{ left: `${leftPos}px`, position: 'absolute' }}
              onPointerDown={() => playNote(note)}
            >
              <span className="key-label">{note.label}</span>
            </div>
          );
        } else {
          const leftPos = whiteKeyIndex * 48 - 15;
          return (
            <div
              key={note.id}
              className={`black-key ${isActive ? 'active' : ''}`}
              style={{ left: `${leftPos}px` }}
              onPointerDown={() => playNote(note)}
            >
              <span className="key-label">{note.label}</span>
            </div>
          );
        }
      })}
    </div>
  );
}

import { useState } from 'react';
import Piano from './components/Piano';
import { PianoSettings } from './types';

export default function App() {
  const [settings, setSettings] = useState<PianoSettings>({
    volume: 0.5,
    waveType: 'sine',
  });
  const [history, setHistory] = useState<string[]>([]);
  const [isPlayingSong, setIsPlayingSong] = useState(false);
  const [activeNoteId, setActiveNoteId] = useState<string | null>(null);

  const handleNotePlay = (noteName: string) => {
    setHistory((prev) => [noteName, ...prev.slice(0, 19)]);
  };

  const playTwinkleSong = async () => {
    if (isPlayingSong) return;
    setIsPlayingSong(true);

    const song = [
      'C4', 'C4', 'G4', 'G4', 'A4', 'A4', 'G4',
      'F4', 'F4', 'E4', 'E4', 'D4', 'D4', 'C4',
      'G4', 'G4', 'F4', 'F4', 'E4', 'E4', 'D4',
      'G4', 'G4', 'F4', 'F4', 'E4', 'E4', 'D4',
      'C4', 'C4', 'G4', 'G4', 'A4', 'A4', 'G4',
      'F4', 'F4', 'E4', 'E4', 'D4', 'D4', 'C4'
    ];

    for (const note of song) {
      setActiveNoteId(note);
      await new Promise((r) => setTimeout(r, 400));
      setActiveNoteId(null);
      await new Promise((r) => setTimeout(r, 50));
    }

    setIsPlayingSong(false);
  };

  return (
    <div className="piano-app">
      <div className="header">
        <h1>Web Audio ピアノ</h1>
        <p>キーボードまたはマウスで演奏できます（サンプル曲の自動演奏対応）</p>
      </div>

      <div className="controls">
        <div className="slider">
          <label>ボリューム:</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.05"
            value={settings.volume}
            onChange={(e) => setSettings({ ...settings, volume: parseFloat(e.target.value) })}
          />
        </div>

        <button
          className="btn"
          onClick={() => {
            const types: OscillatorType[] = ['sine', 'square', 'sawtooth', 'triangle'];
            const nextType = types[(types.indexOf(settings.waveType) + 1) % types.length];
            setSettings({ ...settings, waveType: nextType });
          }}
        >
          音色: {settings.waveType}
        </button>

        <button
          className="btn"
          disabled={isPlayingSong}
          onClick={playTwinkleSong}
        >
          {isPlayingSong ? '演奏中...' : 'きらきら星を演奏'}
        </button>
      </div>

      <Piano settings={settings} onNotePlay={handleNotePlay} activeNoteId={activeNoteId} />

      <div className="history-panel">
        <h3>演奏履歴</h3>
        <div>{history.length > 0 ? history.join(', ') : 'まだ演奏されていません'}</div>
      </div>
    </div>
  );
}
